pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: a target contract_address and parallel arrays tos, vs
    // We must let the fuzzer supply contract_address so it can pick address(0)
    function testFuzz_property(address contract_address, address[] memory tos, uint256[] memory vs) public {
        // Keep admissible domain wide but make arrays non-empty and aligned so transfer would proceed
        // in the reference except for the validAddress check. We do not exclude address(0).
        vm.assume(tos.length == vs.length);
        vm.assume(tos.length > 0);

        // We will call transfer and record whether it reverted or returned normally.
        bool ok;
        try c.transfer(contract_address, tos, vs) {
            ok = true;
        } catch {
            ok = false;
        }

        // The property: when contract_address == address(0), the REFERENCE C always reverts (validAddress forbids zero).
        // Therefore for any fuzz input with contract_address == address(0), ok must be false on the correct contract.
        // The mutant relaxes that check and may allow ok == true for some inputs; our single assertion enforces the
        // universal property the reference guarantees and the mutant will violate for some fuzz case.
        if (contract_address == address(0)) {
            assertTrue(!ok);
        } else {
            // For non-zero addresses we make no further assertions — keep domain wide.
            assertTrue(true);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: the callee contract will be deployed (not fuzzed address) but we fuzz arrays and values
    function testFuzz_property(address filler, address[] memory tos, uint256[] memory vs) public {
        // Keep domain wide: no tight assumes. However ensure arrays are non-empty and equal length
        // because transfer requires tos.length > 0, vs.length > 0 and tos.length == vs.length.
        // Let the fuzzer find such inputs; if it doesn't, skip via assume (still wide).
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        vm.assume(tos.length == vs.length);

        // Deploy an adversarial callee that always returns true for the selector transferFrom
        CalleeAccepting callee = new CalleeAccepting();

        // Build arrays that point all destinations to the deployed callee so low-level calls succeed when invoked
        address[] memory routedTos = new address[](tos.length);
        for (uint i = 0; i < tos.length; i++) routedTos[i] = address(callee);

        // Call into c.transfer with contract_address = address(0) to exercise the validAddress modifier behavior
        bool ok;
        try c.transfer(address(0), routedTos, vs) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: the reference implementation ALWAYS reverts for contract_address == address(0)
        // so ok must be false for ALL admissible inputs. The mutant that removed the zero-address require can
        // return true for some inputs (when the callee accepts the low-level calls), causing this assertion to fail.
        assertTrue(!ok);
    }
}

// Minimal adversarial helper: accepts the low-level call to transferFrom and returns success
contract CalleeAccepting {
    // Accept any call and return true data when selector matches transferFrom
    fallback() external payable {
        // simply return success (no revert). Return empty data is interpreted as success by low-level call.
    }
}
